/bin/bash -lc "python - <<'PY'
from bioblend.galaxy import GalaxyInstance
import os, json
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'], key=key)
tool=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/devteam/freebayes/freebayes/1.3.10+galaxy1', io_details=True)
# print relevant conditionals and children names/defaults
def summarize(inp,path=''):
    cur=(path+'|'+inp.get('name','')).strip('|')
    typ=inp.get('type')
    if inp.get('name') in ['target_limit_type','coverage_options','options_type','output_options','reference_source'] or typ=='conditional':
        print('COND',cur,'test',inp.get('test_param',{}).get('name'), 'default', inp.get('test_param',{}).get('value'), 'cases',[c.get('value') for c in inp.get('cases',[])])
        for c in inp.get('cases',[]):
            print(' case', c.get('value'), [(s.get('name'),s.get('type'),s.get('value')) for s in c.get('inputs',[])[:20]])
    if typ=='conditional':
        for c in inp.get('cases',[]):
            for s in c.get('inputs',[]): summarize(s, cur)
    elif typ=='section':
        for s in inp.get('inputs',[]): summarize(s, cur)
for inp in tool['inputs']:
    summarize(inp)
